/// <summary>
/// CB748_PricingConditions
/// Add validation for custom rebate fields
/// </summary>
/// <returns>True if record validation successful; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (!this.METIsOffRemittance
    &&  this.METFollowTransactionTaxItemGroup)
    {            
        ret = checkFailed(strFmt("@MET:OffRemitChargeCodeValidation", fieldPName(MarkupTable, METFollowTransactionTaxItemGroup), fieldPName(MarkupTable, METIsOffRemittance)));
    }

    return ret;
}
